diff --git a/crates/ignore/tests/parallel_walk_panic.rs b/crates/ignore/tests/parallel_walk_panic.rs
new file mode 100644
index 0000000..784a5ed
--- /dev/null
+++ b/crates/ignore/tests/parallel_walk_panic.rs
@@ -0,0 +1,91 @@
+// Reproduction for: "ignore: parallel walker occasionally hangs if visitor
+// panics".
+//
+// `WalkParallel::run()` (and `WalkParallel::visit()`) must not hang when the
+// visitor panics on one of the worker threads. The expected behavior is that
+// the call returns by propagating the panic to the caller.
+//
+// The walk runs on a helper thread and the test waits for it with a deadline,
+// so that a hang shows up as a test failure rather than as a stuck process.
+// Only the hang is asserted: the contents of the propagated panic message are
+// deliberately not checked.
+
+use std::fs;
+use std::panic::{self, AssertUnwindSafe};
+use std::path::PathBuf;
+use std::sync::mpsc::{self, RecvTimeoutError};
+use std::thread;
+use std::time::Duration;
+
+use ignore::WalkBuilder;
+
+/// How long to wait for the walk to finish before declaring it hung. A walk
+/// of a directory with one file takes a few milliseconds when it works.
+const DEADLINE: Duration = Duration::from_secs(10);
+
+fn scratch_dir(name: &str) -> PathBuf {
+    let dir = std::env::temp_dir().join(format!(
+        "ignore-parallel-walk-panic-{}-{}",
+        std::process::id(),
+        name
+    ));
+    let _ = fs::remove_dir_all(&dir);
+    fs::create_dir_all(&dir).unwrap();
+    fs::write(dir.join("foo.txt"), "").unwrap();
+    dir
+}
+
+/// Runs a parallel walk whose visitor always panics and checks that
+/// `WalkParallel::run()` finishes (by panicking) instead of hanging.
+fn assert_panicking_visitor_does_not_hang(name: &str, threads: usize) {
+    let dir = scratch_dir(name);
+    let root = dir.clone();
+    let (tx, rx) = mpsc::channel();
+    // Intentionally not joined: if the walk hangs, this thread (and the
+    // worker threads it spawned) never finish and are torn down when the test
+    // process exits.
+    thread::spawn(move || {
+        let result = panic::catch_unwind(AssertUnwindSafe(|| {
+            WalkBuilder::new(&root)
+                .threads(threads)
+                .build_parallel()
+                .run(|| Box::new(|_| panic!("oops!")));
+        }));
+        let _ = tx.send(result.is_err());
+    });
+    let outcome = rx.recv_timeout(DEADLINE);
+    let _ = fs::remove_dir_all(&dir);
+    match outcome {
+        Ok(true) => {} // the panic was propagated to the caller
+        Ok(false) => panic!(
+            "WalkParallel::run() returned normally ({threads} threads), \
+             but the visitor panicked",
+        ),
+        Err(RecvTimeoutError::Timeout) => panic!(
+            "WalkParallel::run() hung ({threads} threads): still running \
+             {DEADLINE:?} after the visitor panicked",
+        ),
+        Err(RecvTimeoutError::Disconnected) => {
+            panic!("walk thread died without reporting a result")
+        }
+    }
+}
+
+// Same walk as `panic_in_parallel` from the report: 40 threads, one file, and
+// a visitor that panics with "oops!".
+#[test]
+fn panic_in_visitor_does_not_hang_40_threads() {
+    assert_panicking_visitor_does_not_hang("t40", 40);
+}
+
+#[test]
+fn panic_in_visitor_does_not_hang_2_threads() {
+    assert_panicking_visitor_does_not_hang("t2", 2);
+}
+
+// Control: with a single worker thread there is nobody left waiting for the
+// panicked worker, and the panic is propagated.
+#[test]
+fn panic_in_visitor_does_not_hang_1_thread() {
+    assert_panicking_visitor_does_not_hang("t1", 1);
+}
